import random
from typing import List, Tuple, Dict
from app.models.game import TetrominoType

SHAPES: Dict[TetrominoType, List[Tuple[int, int]]] = {
    'I': [(0, 0), (0, 1), (0, 2), (0, 3)],
    'O': [(0, 0), (0, 1), (1, 0), (1, 1)],
    'T': [(0, 1), (1, 0), (1, 1), (1, 2)],
    'S': [(0, 1), (0, 2), (1, 0), (1, 1)],
    'Z': [(0, 0), (0, 1), (1, 1), (1, 2)],
    'J': [(0, 0), (1, 0), (1, 1), (1, 2)],
    'L': [(0, 2), (1, 0), (1, 1), (1, 2)],
}

def get_random_piece_type() -> TetrominoType:
    return random.choice(list(SHAPES.keys()))

def get_relative_cells(piece_type: TetrominoType) -> List[Tuple[int, int]]:
    return SHAPES[piece_type]

from typing import List, Optional, Tuple, Literal
from app.models.game import GameStateModel, ActivePieceModel, TetrominoType

def is_legal_position(board: List[List[Optional[str]]], relative_cells: List[Tuple[int, int]], origin: Tuple[int, int]) -> bool:
    for r, c in relative_cells:
        abs_row = origin[0] + r
        abs_col = origin[1] + c
        if abs_row < 0 or abs_row >= 20 or abs_col < 0 or abs_col >= 10:
            return False
        if board[abs_row][abs_col] is not None:
            return False
    return True

def lock_piece(board: List[List[Optional[str]]], active_piece_type: str, absolute_cells: List[Tuple[int, int]]) -> None:
    for r, c in absolute_cells:
        if 0 <= r < 20 and 0 <= c < 10:
            board[r][c] = active_piece_type

def clear_lines(board: List[List[Optional[str]]]) -> List[List[Optional[str]]]:
    # Completed rows: rows where all 10 columns are filled with non-null settled blocks
    new_board = [row for row in board if any(cell is None for cell in row)]
    cleared_count = len(board) - len(new_board)
    # Insert empty rows at the top to maintain the 20-row height
    for _ in range(cleared_count):
        new_board.insert(0, [None] * 10)
    return new_board

def tick_game(state: GameStateModel) -> GameStateModel:
    if state.status == "game_over":
        return state

    if state.active_piece is None:
        return state

    from app.domain.pieces import get_relative_cells, get_random_piece_type

    active = state.active_piece
    relative_cells = get_relative_cells(active.type)

    # Try moving down
    next_origin = (active.origin[0] + 1, active.origin[1])
    if is_legal_position(state.board, relative_cells, next_origin):
        active.origin = next_origin
        active.cells = [(next_origin[0] + r, next_origin[1] + c) for r, c in relative_cells]
    else:
        # Trigger locking sequence
        lock_piece(state.board, active.type, active.cells)

        # Check Req-26: "The game status MUST transition from 'playing' to 'game_over' if,
        # at the time of a gravity tick, the active piece is already locked at row 0 and cannot move down."
        is_locked_at_row_zero = any(r == 0 for r, c in active.cells) or active.origin[0] == 0

        # Clear active piece
        state.active_piece = None

        # Clear lines
        state.board = clear_lines(state.board)

        if is_locked_at_row_zero:
            state.status = "game_over"
        else:
            # Spawn a new random piece
            new_type = get_random_piece_type()
            new_rel = get_relative_cells(new_type)
            spawn_origin = (0, 3)
            if is_legal_position(state.board, new_rel, spawn_origin):
                state.active_piece = ActivePieceModel(
                    type=new_type,
                    origin=spawn_origin,
                    cells=[(spawn_origin[0] + r, spawn_origin[1] + c) for r, c in new_rel]
                )
            else:
                state.status = "game_over"
                state.active_piece = None

    return state

def move_game(state: GameStateModel, direction: Literal['left', 'right', 'down']) -> GameStateModel:
    if state.status == "game_over":
        return state

    if state.active_piece is None:
        return state

    from app.domain.pieces import get_relative_cells

    active = state.active_piece
    relative_cells = get_relative_cells(active.type)

    if direction == "left":
        next_origin = (active.origin[0], active.origin[1] - 1)
        if is_legal_position(state.board, relative_cells, next_origin):
            active.origin = next_origin
            active.cells = [(next_origin[0] + r, next_origin[1] + c) for r, c in relative_cells]
    elif direction == "right":
        next_origin = (active.origin[0], active.origin[1] + 1)
        if is_legal_position(state.board, relative_cells, next_origin):
            active.origin = next_origin
            active.cells = [(next_origin[0] + r, next_origin[1] + c) for r, c in relative_cells]
    elif direction == "down":
        return tick_game(state)

    return state

export type TetrominoType = 'I' | 'O' | 'T' | 'S' | 'Z' | 'J' | 'L';

export type GameStatus = 'playing' | 'game_over';

export interface ActivePiece {
  type: TetrominoType;
  origin: [number, number]; // [row, col]
  cells: [number, number][]; // absolute coordinates on the board [row, col][]
}

export interface GameState {
  id: string;
  board: (string | null)[][]; // 20 rows of 10 columns
  active_piece: ActivePiece | null;
  status: GameStatus;
}

import { GameState } from './types';

const API_BASE = '/api/games';

export async function createGame(): Promise<GameState> {
  const response = await fetch(API_BASE, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
  });
  if (!response.ok) {
    throw new Error('Failed to create game session');
  }
  return response.json();
}

export async function getGame(id: string): Promise<GameState> {
  const response = await fetch(`${API_BASE}/${id}`);
  if (!response.ok) {
    throw new Error(`Failed to retrieve game session ${id}`);
  }
  return response.json();
}

export async function tickGame(id: string): Promise<GameState> {
  const response = await fetch(`${API_BASE}/${id}/tick`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
  });
  if (!response.ok) {
    throw new Error(`Failed to tick game session ${id}`);
  }
  return response.json();
}

export async function moveGame(id: string, direction: 'left' | 'right' | 'down'): Promise<GameState> {
  const response = await fetch(`${API_BASE}/${id}/move`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ direction }),
  });
  if (!response.ok) {
    throw new Error(`Failed to move game session ${id} direction ${direction}`);
  }
  return response.json();
}

import { useEffect, useState, useRef } from 'react';
import { GameState } from './types';
import { createGame, tickGame, moveGame } from './api';
import { TetrisBoard } from './components/TetrisBoard';
import { GameStatus } from './components/GameStatus';

export default function App() {
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // Semaphore / Lock to prevent overlapping async API calls and race conditions
  const pendingRequest = useRef<boolean>(false);

  // Helper to start or restart the game
  const startNewGame = async () => {
    if (pendingRequest.current) return;
    pendingRequest.current = true;
    setLoading(true);
    setError(null);
    try {
      const state = await createGame();
      setGameState(state);
    } catch (err) {
      console.error(err);
      setError('Could not connect to the Tetris API. Make sure the backend server is running.');
    } finally {
      setLoading(false);
      pendingRequest.current = false;
    }
  };

  // Start game on mount
  useEffect(() => {
    startNewGame();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Set up the automatic gravity tick (Req-31) every 500 ms
  useEffect(() => {
    if (!gameState || gameState.status === 'game_over') return;

    const intervalId = setInterval(async () => {
      // Skip this tick if another request is currently in flight
      if (pendingRequest.current) return;

      pendingRequest.current = true;
      try {
        const updatedState = await tickGame(gameState.id);
        setGameState(updatedState);
      } catch (err) {
        console.error('Gravity tick failed:', err);
      } finally {
        pendingRequest.current = false;
      }
    }, 500);

    return () => clearInterval(intervalId);
  }, [gameState]);

  // Set up keyboard control listeners (Req-32) with throttle check (Req-33)
  useEffect(() => {
    if (!gameState || gameState.status === 'game_over') return;

    const handleKeyDown = async (event: KeyboardEvent) => {
      let direction: 'left' | 'right' | 'down' | null = null;

      if (event.key === 'ArrowLeft') {
        direction = 'left';
      } else if (event.key === 'ArrowRight') {
        direction = 'right';
      } else if (event.key === 'ArrowDown') {
        direction = 'down';
      }

      if (!direction) return;

      // Prevent default scrolling behavior for arrow keys
      event.preventDefault();

      // Skip input if another request is currently in flight (Req-33)
      if (pendingRequest.current) return;

      pendingRequest.current = true;
      try {
        const updatedState = await moveGame(gameState.id, direction);
        setGameState(updatedState);
      } catch (err) {
        console.error('Movement failed:', err);
      } finally {
        pendingRequest.current = false;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState]);

  return (
    <div className="app-container">
      <header className="app-header">
        <h1>Tetris Study Studio</h1>
        <p className="subtitle">Stage 1 — Option A (Server-Authoritative, Rotation-Free)</p>
      </header>

      <main className="game-container">
        {loading && !gameState && (
          <div className="panel loading-panel">
            <p>Initializing Tetris Session...</p>
          </div>
        )}

        {error && (
          <div className="panel error-panel">
            <p className="error-message">{error}</p>
            <button onClick={startNewGame} className="btn-retry">
              Retry Connection
            </button>
          </div>
        )}

        {gameState && (
          <>
            <div className="board-section">
              <TetrisBoard gameState={gameState} />
            </div>
            <div className="status-section">
              <GameStatus 
                gameState={gameState} 
                onRestart={startNewGame} 
                isLoading={loading}
              />
            </div>
          </>
        )}
      </main>
    </div>
  );
}

import React from 'react';
import { GameState } from '../types';

interface TetrisBoardProps {
  gameState: GameState;
}

export const TetrisBoard: React.FC<TetrisBoardProps> = ({ gameState }) => {
  const { board, active_piece } = gameState;

  // Render a 20x10 grid.
  // We can map over the rows and columns.
  return (
    <div className="tetris-board" data-status={gameState.status}>
      {board.map((row, rIndex) => (
        <div key={rIndex} className="board-row">
          {row.map((cell, cIndex) => {
            // Check if this cell is occupied by the active piece
            const isActiveCell = active_piece
              ? active_piece.cells.some(
                  ([cellRow, cellCol]) => cellRow === rIndex && cellCol === cIndex
                )
              : false;

            // Determine the tetromino type/color of this cell
            const cellType = cell || (isActiveCell && active_piece ? active_piece.type : null);

            return (
              <div
                key={cIndex}
                className={`board-cell ${cellType ? `cell-${cellType}` : 'cell-empty'} ${
                  isActiveCell ? 'cell-active' : ''
                }`}
                data-row={rIndex}
                data-col={cIndex}
                data-type={cellType || 'empty'}
              />
            );
          })}
        </div>
      ))}
    </div>
  );
};

import { describe, test, expect } from 'vitest';
import { render } from '@testing-library/react';
import { TetrisBoard } from './TetrisBoard';
import { GameState } from '../types';

describe('TetrisBoard Component', () => {
  const mockGameState: GameState = {
    id: 'test-uuid',
    board: Array.from({ length: 20 }, () => Array(10).fill(null)),
    active_piece: {
      type: 'I',
      origin: [0, 3],
      cells: [[0, 3], [0, 4], [0, 5], [0, 6]],
    },
    status: 'playing',
  };

  test('renders 20x10 board cell grid correctly', () => {
    const { container } = render(<TetrisBoard gameState={mockGameState} />);
    const board = container.querySelector('.tetris-board');
    expect(board).not.toBeNull();

    const cells = container.querySelectorAll('.board-cell');
    expect(cells.length).toBe(200); // 20 * 10
  });

  test('correctly overlays the active piece on the board cells', () => {
    const { container } = render(<TetrisBoard gameState={mockGameState} />);

    // Check cell (0, 3) which is part of active piece
    const activeCell = container.querySelector('[data-row="0"][data-col="3"]');
    expect(activeCell).not.toBeNull();
    expect(activeCell?.classList.contains('cell-I')).toBe(true);
    expect(activeCell?.classList.contains('cell-active')).toBe(true);

    // Check empty cell (5, 5)
    const emptyCell = container.querySelector('[data-row="5"][data-col="5"]');
    expect(emptyCell).not.toBeNull();
    expect(emptyCell?.classList.contains('cell-empty')).toBe(true);
  });
});

import React from 'react';
import { GameState } from '../types';

interface GameStatusProps {
  gameState: GameState;
  onRestart: () => void;
  isLoading: boolean;
}

export const GameStatus: React.FC<GameStatusProps> = ({ gameState, onRestart, isLoading }) => {
  const { id, status, active_piece } = gameState;

  return (
    <div className="game-status-panel">
      <h2>Game Status</h2>

      <div className="status-item">
        <span className="status-label">Session ID:</span>
        <span className="status-value session-id">{id}</span>
      </div>

      <div className="status-item">
        <span className="status-label">Status:</span>
        <span className={`status-value game-state-${status}`}>
          {status.toUpperCase()}
        </span>
      </div>

      <div className="status-item">
        <span className="status-label">Active Tetromino:</span>
        <span className="status-value active-piece-type">
          {active_piece ? active_piece.type : 'None'}
        </span>
      </div>

      {status === 'game_over' && (
        <div className="game-over-banner">
          <h3>GAME OVER</h3>
          <p>Locked pieces reached the top!</p>
        </div>
      )}

      <div className="actions">
        <button 
          onClick={onRestart} 
          disabled={isLoading}
          className="btn-restart"
        >
          {isLoading ? 'Loading...' : 'Start New Game'}
        </button>
      </div>

      <div className="instructions">
        <h3>Controls</h3>
        <ul>
          <li><strong>Left:</strong> <kbd>ArrowLeft</kbd> (<kbd>←</kbd>)</li>
          <li><strong>Right:</strong> <kbd>ArrowRight</kbd> (<kbd>→</kbd>)</li>
          <li><strong>Down:</strong> <kbd>ArrowDown</kbd> (<kbd>↓</kbd>)</li>
        </ul>
        <p className="note">Note: Piece rotation is not supported in Stage 1 Option A.</p>
      </div>
    </div>
  );
};

