import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, fireEvent, act, waitFor } from '@testing-library/react';
import App from './App';
import { GameState } from './types';

describe('App Component Stage 2 UI and Concurrency', () => {
  const initialMockState: GameState = {
    id: 'game-uuid-1',
    board: Array.from({ length: 20 }, () => Array(10).fill(null)),
    active_piece: {
      type: 'I',
      origin: [0, 3],
      cells: [[0, 3], [0, 4], [0, 5], [0, 6]],
    },
    status: 'playing',
    score: 0,
    total_lines: 0,
    level: 1,
    gravity_interval_ms: 500,
    next_piece: 'O',
    hold_piece: null,
    can_hold: true,
  };

  const nextMockState: GameState = {
    ...initialMockState,
    score: 100,
    total_lines: 1,
  };

  beforeEach(() => {
    vi.useFakeTimers();
    vi.spyOn(globalThis, 'fetch');
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.useRealTimers();
  });

  test('renders Stage 2 HUD and Next/Hold panels correctly', async () => {
    // Mock the game creation API response
    (globalThis.fetch as any).mockResolvedValueOnce({
      ok: true,
      json: async () => initialMockState,
    });

    render(<App />);

    // Fast-forward to mount and API fetch
    await act(async () => {
      await vi.runAllTimersAsync();
    });

    // Check HUD elements are visible and display correct values
    expect(screen.getByText('Score:')).toBeDefined();
    expect(screen.querySelector('.score-value')?.textContent).toBe('0');

    expect(screen.getByText('Lines:')).toBeDefined();
    expect(screen.querySelector('.lines-value')?.textContent).toBe('0');

    expect(screen.getByText('Level:')).toBeDefined();
    expect(screen.querySelector('.level-value')?.textContent).toBe('1');

    expect(screen.getByText('Gravity:')).toBeDefined();
    expect(screen.querySelector('.gravity-value')?.textContent).toBe('500 ms');

    // Check Preview and Hold labels
    expect(screen.getByText('Hold Piece')).toBeDefined();
    expect(screen.getByText('Next Piece')).toBeDefined();
    expect(screen.getByText('AVAILABLE')).toBeDefined();
  });

  test('FIFO queue serializes rapid manual movements correctly', async () => {
    let resolveFirstFetch: any;
    let resolveSecondFetch: any;

    const firstFetchPromise = new Promise<any>((resolve) => {
      resolveFirstFetch = resolve;
    });
    const secondFetchPromise = new Promise<any>((resolve) => {
      resolveSecondFetch = resolve;
    });

    // We expect 1 game creation, followed by 2 movement requests.
    // 1st fetch: game creation
    (globalThis.fetch as any).mockResolvedValueOnce({
      ok: true,
      json: async () => initialMockState,
    });

    // 2nd fetch: 1st manual move (delayed resolution)
    (globalThis.fetch as any).mockImplementationOnce(() => firstFetchPromise);

    // 3rd fetch: 2nd manual move (delayed resolution)
    (globalThis.fetch as any).mockImplementationOnce(() => secondFetchPromise);

    render(<App />);

    // Load initial game
    await act(async () => {
      await vi.runAllTimersAsync();
    });

    expect(globalThis.fetch).toHaveBeenCalledTimes(1);

    // Trigger first move (Left)
    fireEvent.keyDown(window, { key: 'ArrowLeft' });
    // Trigger second move (Left) immediately after
    fireEvent.keyDown(window, { key: 'ArrowLeft' });

    // FIFO requirement: the second fetch must NOT be dispatched yet
    // because the first is still pending network resolution!
    expect(globalThis.fetch).toHaveBeenCalledTimes(2);

    // Now, resolve the first move's fetch response
    const firstMoveState: GameState = {
      ...initialMockState,
      active_piece: {
        type: 'I',
        origin: [0, 2],
        cells: [[0, 2], [0, 3], [0, 4], [0, 5]],
      },
    };

    await act(async () => {
      resolveFirstFetch({
        ok: true,
        json: async () => firstMoveState,
      });
      // Allow microtasks to run so the promise chain advances
      await Promise.resolve();
      await Promise.resolve();
    });

    // Now the first move is fully parsed, so the second move should be dispatched!
    expect(globalThis.fetch).toHaveBeenCalledTimes(3);

    const secondMoveState: GameState = {
      ...initialMockState,
      active_piece: {
        type: 'I',
        origin: [0, 1],
        cells: [[0, 1], [0, 2], [0, 3], [0, 4]],
      },
    };

    await act(async () => {
      resolveSecondFetch({
        ok: true,
        json: async () => secondMoveState,
      });
      await Promise.resolve();
      await Promise.resolve();
    });

    // Verify final state is reflected correctly
    expect(screen.querySelector('.active-piece-type')?.textContent).toBe('I');
  });

  test('Restart immediately preempts and discards pending/stale older generation completions', async () => {
    let resolveStaleMove: any;
    const staleMovePromise = new Promise<any>((resolve) => {
      resolveStaleMove = resolve;
    });

    // 1. Initial game creation
    (globalThis.fetch as any).mockResolvedValueOnce({
      ok: true,
      json: async () => initialMockState,
    });

    // 2. A manual move is triggered, but becomes stale/delayed
    (globalThis.fetch as any).mockImplementationOnce(() => staleMovePromise);

    // 3. Game restart create request
    const restartedMockState: GameState = {
      ...initialMockState,
      id: 'game-uuid-restarted-2',
      score: 500, // distinguishable score
    };
    (globalThis.fetch as any).mockResolvedValueOnce({
      ok: true,
      json: async () => restartedMockState,
    });

    render(<App />);

    // Load initial game
    await act(async () => {
      await vi.runAllTimersAsync();
    });

    // Trigger stale move
    fireEvent.keyDown(window, { key: 'ArrowLeft' });
    expect(globalThis.fetch).toHaveBeenCalledTimes(2); // create, then move

    // Restart game before the move resolves
    const restartBtn = screen.getByRole('button', { name: 'Start New Game' });
    await act(async () => {
      fireEvent.click(restartBtn);
    });

    // New game creation should have been dispatched immediately
    expect(globalThis.fetch).toHaveBeenCalledTimes(3);

    // Let's resolve the stale move now (which should be discarded because it belongs to the old generation!)
    const staleState: GameState = {
      ...initialMockState,
      score: 99999, // Should NOT be written
    };

    await act(async () => {
      resolveStaleMove({
        ok: true,
        json: async () => staleState,
      });
      await Promise.resolve();
      await Promise.resolve();
    });

