        ok: true,
        json: async () => initialMockState,
      });

      render(<App />);

      await act(async () => {
        await vi.runOnlyPendingTimersAsync();
      });

      const clearTimeoutSpy = vi.spyOn(globalThis, 'clearTimeout');

      fireEvent.keyDown(window, { key: 'ArrowLeft' });

      expect(clearTimeoutSpy).toHaveBeenCalled();
    } finally {
      vi.useRealTimers();
      vi.restoreAllMocks();
    }
  });
});

