  --color-T: #a000f0; /* Purple */
  --color-S: #00f000; /* Green */
  --color-Z: #f00000; /* Red */
  --color-J: #0000f0; /* Blue */
  --color-L: #f0a000; /* Orange */
}

body {
  margin: 0;
  display: flex;
  place-content: center;
  min-width: 320px;
  min-height: 100vh;
}

#root {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
  box-sizing: border-box;
}

/* App Container */
.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
  width: 100%;
}

.app-header {
  text-align: center;
}

.app-header h1 {
  margin: 0 0 0.5rem 0;
  font-size: 2.5rem;
  letter-spacing: 1px;
  background: linear-gradient(135deg, #00f0f0, #a000f0);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.subtitle {
  margin: 0;
  font-size: 1rem;
  color: #8f9cae;
}

/* Core Layout */
.game-container {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: flex-start;
  gap: 2.5rem;
  width: 100%;
}

.panel {
  background: rgba(30, 34, 47, 0.8);
  border: 1px solid #2f364d;
  border-radius: 12px;
  padding: 2rem;
  text-align: center;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}

.loading-panel, .error-panel {
  max-width: 450px;
  width: 100%;
}

.error-message {
  color: #ff4a5a;
  margin-bottom: 1.5rem;
}

